
import type { PricingAmounts } from './PricingAmounts.js';
import type { ReturnShipmentLineItemAllocation } from './ReturnShipmentLineItemAllocation.js';
import type { SettlementAmounts } from './SettlementAmounts.js';
import type { ShippingDimensions } from './ShippingDimensions.js';
import type { ShippingWeight } from './ShippingWeight.js';

export type Package = { "carrier"?: string; /** Creation timestamp. Format: date-time. */ "created_at"?: string; /** Package delivery timestamp. Format: date-time. */ "delivered_at"?: string; "dimensions"?: ShippingDimensions; /** Caller-owned identifier for this resource in an external system. Caller-owned package identifier in external_system. Set with external_system to enable duplicate detection and replay for that provider reference. maxLength: 255. */ "external_reference_id"?: string; /** External carrier, aggregator, or fulfillment platform name for this package. Set with external_reference_id to enable duplicate detection and replay for that provider reference; without external_reference_id this is stored as provenance only. */ "external_system"?: string; "fulfillment_id": string; /** Merchant or integration supplied HTTPS shipping-label URL for authenticated merchant workflows. Non-Flint URLs must include external_system for provenance. Flint does not currently manage label file hosting or buyer-facing label downloads. Omitted for a checkout session credential that doesn't act for the customer the buyer verified. */ "label_url"?: string; "metadata"?: Record<string, string>; "order"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; "fulfillment_status"?: "not_fulfilled" | "partially_fulfilled" | "fulfilled" | "canceled" | "not_applicable" | "closed" | (string & {}); "order_id": string; "order_number"?: string; "payment_intent_ids"?: Array<string>; "payment_status": "unpaid" | "partially_paid" | "paid" | (string & {}); "pricing_amounts": PricingAmounts; "refund_status": "none" | "partially_refunded" | "refunded" | (string & {}); "settlement_amounts": SettlementAmounts; "status": "open" | "closed" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "order_id": string; "package_id": string; /** Return this package belongs to. Present only on packages of return shipments. */ "return_id"?: string; /** Return line quantities allocated to this parcel. Present only on packages of return shipments. */ "return_line_items"?: Array<ReturnShipmentLineItemAllocation>; "service_code"?: string; "shipment_id": string; /** Package handoff timestamp. Format: date-time. */ "shipped_at"?: string; /** Current package lifecycle state. Package states are the source used to derive shipment status. - `created`: The package record exists but has not been packed or handed off. - `packed`: The package is packed and awaiting carrier handoff. - `shipped`: The package was handed to the carrier. - `in_transit`: The carrier is moving the package through its network. - `out_for_delivery`: The package is on its final delivery route. - `delivered`: The carrier reported successful delivery. - `delivery_attempted`: The carrier attempted delivery but did not complete it. Follow the carrier instructions before retrying delivery. - `exception`: A carrier exception is blocking normal progress. Resolve the carrier-reported issue. - `returned`: The package was returned toward or to its origin. - `voided`: The package was voided and will not continue through delivery. */ "status": "created" | "packed" | "shipped" | "in_transit" | "out_for_delivery" | "delivered" | "delivery_attempted" | "exception" | "returned" | "voided" | (string & {}); "status_reason"?: string; /** Read-only actions currently supported for this package. */ "supported_actions": Array<"mark_delivered" | "mark_delivery_attempted" | "mark_exception" | "mark_in_transit" | "mark_out_for_delivery" | "mark_packed" | "mark_returned" | "mark_shipped" | (string & {})>; /** Omitted for a checkout session credential that doesn't act for the customer the buyer verified. */ "tracking_number"?: string; /** Absolute HTTPS carrier tracking URL. Embedded URL credentials are rejected. Omitted for a checkout session credential that doesn't act for the customer the buyer verified. */ "tracking_url"?: string; /** Last update timestamp. Format: date-time. */ "updated_at"?: string; /** Monotonic package version for expected_version checks. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version": string; "weight"?: ShippingWeight; };
